import roster from "./roster.js";
import { weigh } from "./gauges.js";

export const MAX_PILE = 6;
const className = "crate";

export class Crate {
  constructor(id, weight) {
    this.id = id;
    this.weight = weight;
    this.shut = false;
  }

  latch() {
    this.shut = true;
    roster.record(this.id, "shut");
    return this;
  }

  get tag() {
    return `${className}-${this.id}`;
  }
}

export class ColdCrate extends Crate {
  constructor(id, weight, degrees) {
    super(id, weight);
    this.degrees = degrees;
  }
}

class Skid {
  constructor() {
    this.crates = [];
  }

  add(crate) {
    if (this.crates.length >= MAX_PILE) {
      throw new CrateError("no room left");
    }
    this.crates.push(crate);
  }

  get weight() {
    return this.crates.reduce((sum, crate) => sum + weigh(crate), 0);
  }
}

class CrateError extends Error {}

export const Lidded = class extends Crate {
  constructor(id, weight) {
    super(id, weight);
    this.shut = true;
  }
};

const Fragile = class FragileCrate extends Crate {};

export function classify(crate) {
  if (crate instanceof ColdCrate) return "cold";
  if (crate instanceof Fragile) return "fragile";
  return crate.shut ? "shut" : "open";
}

