// Crates, and what holds them.
import ledger from "./ledger.js";
import { weigh } from "./scales.js";

export const MAX_STACK = 6;
const className = "crate";

export class Crate {
  constructor(id, weight) {
    this.id = id;
    this.weight = weight;
    this.shut = false;
  }

  seal() {
    this.shut = true;
    ledger.record(this.id, "shut");
    return this;
  }

  get tag() {
    return `${className}-${this.id}`;
  }
}

export class ColdCrate extends Crate {
  constructor(id, weight, degrees) {
    super(id, weight);
    this.degrees = degrees;
  }
}

class Pallet {
  constructor() {
    this.crates = [];
  }

  add(crate) {
    if (this.crates.length >= MAX_STACK) {
      throw new CrateError("no room left");
    }
    this.crates.push(crate);
  }

  get weight() {
    return this.crates.reduce((sum, crate) => sum + weigh(crate), 0);
  }
}

class CrateError extends Error {}

export const Lidded = class extends Crate {
  constructor(id, weight) {
    super(id, weight);
